sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // MSSCUSTODY-4148 - Copy fields from maker to checker tasks
    var swiftSource = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_swift_populate_swift_exception');
    var mkrTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
    mkrTask.addEncodedQuery('trade_id.sys_id=' + current.trade_id + '^trade_task_type=Maker');
    mkrTask.orderByDesc('sys_created_on');
    mkrTask.setLimit(1);
    mkrTask.query();
    if (mkrTask.next()) {
        current.fxr_td = mkrTask.fxr_td;
        current.settlement_date = mkrTask.settlement_date;
        current.value_date = mkrTask.value_date;
        var trdSourceSystem = mkrTask.trade_id.source_system.toString();
        if (swiftSource.indexOf(trdSourceSystem) > -1) { // Limited to GCS Swift Trades
            current.ghss_trade_ref_id = mkrTask.swift_linking_reference_id.getDisplayValue().toString();
        }
    }




})(current, previous);
